// ---------- que cada persona tenga un aspecto acorde a su género ----------
const FEM_ONLY=new Set(['melena','coleta','mono','larga','ondas','bob','trenzas','boxbraids','puffs','bantu','flequillo']);
const MASC_STY=['corto','tupe','rapado','fade','twa','calvo','rizos'];
function personG(p){if(p.k==='madre')return 'f';if(p.g==='o'||p.g==='m')return 'm';if(p.g==='a'||p.g==='f')return 'f';if(p.g==='x'||p.g==='e')return 'x';return /a$/.test(p.n)?'f':'m';}
function personCh(p){const g=personG(p);const ch=randomChar(g);ch.name=p.n;if(p.k==='madre'){ch.age=58;ch.hair='#bdbdbd';ch.style='mono';ch.beard='no';}else ch.age=p.age||30;return ch;}
function fixLook(ch,g){if(!ch)return;g=g||ch.g;if(g==='m'&&FEM_ONLY.has(ch.style))ch.style=pickR(MASC_STY);if(g==='f'&&ch.beard&&ch.beard!=='no')ch.beard='no';if(g==='m'&&(ch.outfit==='vestido'||ch.outfit==='falda')&&typeof dressUp==='function')dressUp(ch,pickR(['hiphop','vaquera','basico','punto']));if(ch.rf&&ch.rf.face&&!ch.rf.face._g){ch.rf.face.estructura=g==='f'?'suave':g==='m'?'marcada':'media';ch.rf.face._g=1;if(g==='m'){ch.rf.makeup=false;}}ch.g=g;}
